<?php use App\Core\Csrf; $base=$portal?'/portal/tickets':'/tickets'; ?>
<header class="page-header compact"><div><a class="back-link" href="<?= $base ?>">← Support Tickets</a><div class="eyebrow">New request</div><h1>Open support ticket</h1><p>Tell us what you need help with and include any useful details.</p></div></header><?php if($errors): ?><div class="alert error"><?= implode('<br>',array_map('htmlspecialchars',$errors)) ?></div><?php endif; ?><form class="record-form ticket-form" method="post" action="<?= $base ?>" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><section class="form-card"><div class="form-heading"><span>01</span><div><h2>Ticket details</h2><p>Choose the right department and urgency.</p></div></div><div class="form-grid"><?php if(!$portal): ?><label>Customer<select name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $customer): ?><option value="<?= (int)$customer['id'] ?>" <?= (int)($ticket['customer_id']??0)===(int)$customer['id']?'selected':'' ?>><?= htmlspecialchars((string)($customer['company_name']?:$customer['contact_name'])) ?> · <?= htmlspecialchars((string)$customer['account_number']) ?></option><?php endforeach; ?></select></label><?php endif; ?><label>Department<select name="department_id" required><option value="">Select department</option><?php foreach($departments as $department): ?><option value="<?= (int)$department['id'] ?>" <?= (int)($ticket['department_id']??0)===(int)$department['id']?'selected':'' ?>><?= htmlspecialchars((string)$department['name']) ?></option><?php endforeach; ?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $value): ?><option value="<?= $value ?>" <?= ($ticket['priority']??'normal')===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></label><label class="wide">Subject<input name="subject" maxlength="190" value="<?= htmlspecialchars((string)($ticket['subject']??'')) ?>" required></label></div></section><section class="form-card"><div class="form-heading"><span>02</span><div><h2>Your message</h2><p>Include steps, dates and error messages where relevant.</p></div></div><label>Message<textarea name="message" rows="9" required><?= htmlspecialchars((string)($ticket['message']??'')) ?></textarea></label><label class="attachment-field">Optional attachment<input type="file" name="attachment" accept=".jpg,.jpeg,.png,.gif,.pdf,.txt,.zip"><small>JPG, PNG, GIF, PDF, TXT or ZIP · maximum 5MB</small></label></section><div class="form-actions"><a class="secondary-button" href="<?= $base ?>">Cancel</a><button class="primary-button">Open ticket</button></div></form>
